import React, { Component, useEffect, useState, useContext, createContext } from 'react'
import Nav from '../comp/Nav'
import Header from '../comp/Header'
import Add from '../comp/Add'
import Reviews from '../comp/Reviews'
import { useLocation } from 'react-router-dom'
import { content_type, getCookie, has_review, to_form_data } from '../extra'
import axios from 'axios'
import ReviewModal from '../comp/ReviewModal'
import { ContextHead } from '../App';

axios.defaults.xsrfHeaderName = "X-CSRFTOKEN";
axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
});
const baseURL = "https://infernovertigo.pythonanywhere.com";

function format(brdString = "?"){
  try{
    const splitString = brdString.split(" ");
    const firstTwo = splitString[0] + " " + splitString[1]+ " ";

    if(splitString[2].length == 4){
      const newString = firstTwo + splitString[2].substring(0,2) + ":" + splitString[2].substring(2,4) + " (JST)";
      return newString;
    }else{
      return brdString;
    }
  }catch(e){
    return "?";
  }
  
}

export const AnimeDetailsCTX = createContext();

const Animedetail = (props) =>{
  const value = useContext(ContextHead);
  const location = useLocation();
  const [synopsis, setSynopsis] = useState(null);
  const [has, setHas] = useState(false);

  //setAll((obj)=>{obj["watched"]=data["watched"]; obj["watched"]=data["watched"]; return obj;});
  const [title, setTitle] = useState("");
  const [episodes, setEpisodes] = useState(null);
  const [broadcast, setBroadcast] = useState("");
  const [type, setType] = useState("");
  const [start_date, setStarts] = useState("");
  const [end_date, setEnds] = useState("");
  const [img, setImg] = useState("");

  //requests items that have to be updated first before reviews is shown
  const [anime_id, setAnimeID] = useState(null);
  const [status, setStatus] = useState(false);
  const [isValid, setValidity] = useState(false);
  const [userEpisodes, setUserEpisodes] = useState(0);
  const [userScore, setUserScore] = useState(0);
  const[showReviewBox, setShow] = useState(false);
  const[review_msg, setMsg] = useState("");
  const[review_rating, setRating] = useState(0);
  const[review_recommend, setRecommend] = useState(0);
  const[requests_done, setDone] = useState(false);

  var inner_id = 0;

  function closeModal() {
    setShow(false);
  }

  //where this page starts the loading
  useEffect(()=>{
    //console.log("page change")
    window.scrollTo(0,0);
    setAnimeID(null);
    setEpisodes(null);
    let anime_name = window.location.href.match("anime/.+$").toString();
    //let inner_id = 0;
    if(props.ready){
      if(anime_name.length > 1){
        const deURI = decodeURI(anime_name.split("/")[1]);
        setTitle(deURI);
        //console.log(deURI)
        async function ensure_finish(){
          const res = await client.post("anime_deta",{
            title:deURI.toString()
          },{
            headers:{
              'Content-Type': 'application/json'
            }
          })
          .then((val)=>{
          
            if(val.data["entity"].length == 0){
              return;
            }
            setSynopsis(()=>val.data["entity"][0]["synopsis"]);
            setImg(()=>val.data["entity"][0]["img_url"]);
            setAnimeID(()=>val.data["entity"][0]["anime_id"]);
            inner_id = val.data["entity"][0]["anime_id"];
            //console.log(val.data["entity"]);
          })
          .catch((err)=>{
            //console.log(err.response)
          })
          .then(async(fin)=>{
            const res = await client.get(`details/animeinfo=${inner_id}`).then((val)=>{
              document.getElementById("nows").innerText = val.data["watching"];
              document.getElementById("mems").innerText = val.data["members"];
              if(val.data["avg"] == null){
                document.getElementById("avg").innerText = "N/A";
              }else{
                document.getElementById("avg").innerText = val.data["avg"];
              }     
            })
            const setting_has = fetch("https://infernovertigo.pythonanywhere.com/has_it", {
              method:"POST",
              body:JSON.stringify({"title":deURI, "session":getCookie("sessionid"), "csrf":getCookie("csrftoken"), "anime_id":inner_id}),
              headers:{
                "Content-Type":"application/json"
              }
            })
            .then((obj)=>{return obj.json()}).then(async(val)=>{
               
              setStatus(val["has"]);

            })
          })
        }
        ensure_finish();
  
        const smaller_res = client.post("anime_detaS", {
          "title":decodeURI(anime_name.split("/")[1])
        },{
          "CONTENT-TYPE":"application/json"
        })
        .then((val)=>{
          if(val.data["entity"].length == 0){
            setDone(true);
            return;
          }
          try{ 
            setEpisodes(()=>val.data["entity"][0]["episodes"]);
            setBroadcast(()=>val.data["entity"][0]["broadcast"]);
            setType(()=>val.data["entity"][0]["type"]);
            setStarts(()=>val.data["entity"][0]["start_date"]);
            setEnds(()=>val.data["entity"][0]["end_date"]);
            setDone(true);
          }
          catch{
            setDone(true);
            return;
          }
        })
      }
    }
  }, [props.ready, location])

  //where the update show stats loads after all the other stuff loads.
  useEffect(()=>{
    if(requests_done){
      fetch(baseURL+"/user/mini_queue",{
        method:"POST",
        body:JSON.stringify({
          "sessionid":getCookie("sessionid"), 
          "csrf":getCookie("csrftoken"), 
          "anime_id":anime_id,
          "user_id":value.userID
        }),
        headers:{
          "Content-Type":"application/json"
        }
      })
      .then((val)=>{return val.json()}).then((data)=>{if(data["logged_in"] && data["valid"]){setValidity(data["valid"]); setUserEpisodes(data["watched"]); setUserScore(data["score"]);}})
    }
  }, [requests_done, anime_id])
  
  function sendVal(e){
    e.target.disabled = true;
    if(status == true){

      const score = document.getElementsByName("userScr")[0];
      const episode = document.getElementsByName("userEp")[0];

      if(isNaN(Number(score.value))){
        score.value = 0;
      }
      if(isNaN(Number(episode.value))){
        episode.value = 0;
      }
      if(score.value > 10){
        score.value = 10;
      }
      /*if(episode.value > episodes){
        episode.value = episodes;
      }*/

      if(episode.value == ""){
        episode.value = episode.placeholder;
      }

      if(score.value == ""){
        score.value = score.placeholder;
      }
      
      client.put("updateV2", {
        light:true,
        session:getCookie("sessionid"),
        csrf:getCookie("csrftoken"),
        watched:episode.value,
        score:score.value,
        anime_id:anime_id
      }).then((val)=>{
        //console.log(val.data)
        if(val.data["status"]){
          //console.log(val.data)
          fetch("https://ligular-noises.000webhostapp.com",{method:"POST", body:to_form_data({"userEpisodes":episode.value, "anime_id":anime_id,
          "user_id":value.userID, "req_url":"/update_episode"}), 
          headers:{"content-type":content_type}})
          const noti = document.getElementById("notifications");
          noti.style.display = "block";
          noti.style.backgroundColor = "green";
          noti.innerText = "Updated Your Data!";
          setTimeout(()=>{
            noti.style.display = "none";
            e.target.disabled = false;
          }, 5000)

          setUserEpisodes(episode.value);
        }
        else{
          const noti = document.getElementById("notifications");
          noti.style.display = "block";
          noti.style.backgroundColor = "red";
          noti.innerText = "Problem updating your list. Please try again later.";
          setTimeout(()=>{
            noti.style.display = "none";
            e.target.disabled = false;
          }, 5000)
        }
      })
      .then((data)=>{
        fetch(baseURL+"/completions", {
          method:"PUT",
          body:JSON.stringify({
              session:getCookie("sessionid"),
              csrf:getCookie("csrftoken"),
          }),
          headers:{
              "content-type":"application/json"
          }
        }).then((variable)=>variable.json())/*.then((final)=>{console.log(final)})*/;
    });
    }else{
      const noti = document.getElementById("notifications");
      noti.style.display = "block";
      noti.style.backgroundColor = "red";
      noti.innerText = "You do not have this show in your list. Please add show to list to update.";
      setTimeout(()=>{
        noti.style.display = "none";
        e.target.disabled = false;
      }, 5000)
    }
  }
  return(
  <>
  <AnimeDetailsCTX.Provider value={{"msg":review_msg, "setMsg":setMsg,
  "review_rating":review_rating, "setRating":setRating, "review_recommend":review_recommend, 
  "setRecommend":setRecommend, "user_id":props.user_id, "anime_id":anime_id, "loggedIn":props.loggedIn, 
  "status":status, "episodes":episodes, "title":title, "username":props.username, "valid":isValid, 
  "userEpisodes":userEpisodes, "inner_id":inner_id}}>

    <ReviewModal show={showReviewBox} setShow={setShow} closeModal={closeModal}/>
    <div id="detail_container">
      {/*<Header loggedIn={props.loggedIn} setLoggedIn={props.setloggedIn}/>
      <Nav showSearch={true}/>*/}
      <h1 className='detail_headers'>{title}</h1>
      <div id="inner_detail_cont">
      
      {false?<></>:<div id="anime_stats_container">

        <p className="detail_stat">Rank: <span id="rank">N/A</span></p>
        <p className="detail_stat">Members: <span id="mems">N/A</span></p>
        <p className="detail_stat">Watching: <span id="nows">N/A</span></p>
        <p className="detail_stat">Avg Score: <span id="avg">N/A</span></p>

      </div>}

        {synopsis!=null?<><div id="img_cont">
          <img src={img} />
        </div>
        <div id="features">
            {props.loggedIn?
              <span id="add_anchor"><Add key={anime_id} title={title} status={status} detailSetStatus={setStatus} anime_id={anime_id} episodes={episodes} session_id={getCookie("sessionid")} csrf={getCookie("csrftoken")}/></span>
              : <></>
            }
            {/*<span><button className='feature_btns'><b>Add to List</b></button></span>*/}
            <span><button disabled={true} className='feature_btns'><b>Video (coming soon)</b></button></span>
            <span><button disabled={true} className='feature_btns'><b>Stats (coming soon)</b></button></span>
            {/*<span><button className='feature_btns'><b>Video</b></button></span>*/}
            {/*<span><button className='feature_btns'><b>Add to List</b></button></span>*/}
        </div>

        {
        props.loggedIn?
        <div id="user_info_details">
          <p>Episodes: <input className="update_info" name="userEp" type="text" placeholder={userEpisodes}/>/<span>{episodes}</span></p>
          <p>Score: <input className="update_info" name="userScr" type="text" placeholder={userScore}/>/<span>10</span></p>
          <button onClick={(e)=>{sendVal(e)}} id="user_info_update_btn">Update</button>
          
          <div id="bottom_row">
            <span style={{display:'block'}} id="update_status"></span>
          </div>
          
        </div>:<></>}

        <div id="synopsis_cont">
          <h3 id="synopsis_title" className='detail_headers'>Synopsis:</h3>
          <p id="synopsis">{synopsis}</p>

          <h3 className="info_header">Information: </h3>
          <div id="additional_info">
            <span><b className="infoHeads">Episodes:</b> {episodes}</span>
            <span><b className="infoHeads">Broadcasted:</b> {format(broadcast)}</span>
            <span><b className="infoHeads">Type:</b> {type}</span>
            <span><b className="infoHeads">Started On:</b> {start_date}</span>
            <span><b className="infoHeads">Ended On:</b> {end_date}</span>
          </div>
        </div></>:<><div class="loader homeLoader"></div><p id="loading_id2" style={{color:"white", fontSize:"30px"}}>Could not load data.</p></>}
      </div>
      
      <div>
        {<h1 className="detail_headers" id="review_header">Reviews</h1>}
        {/*<hr></hr>*/}
        {requests_done && anime_id != null && episodes != null ? <Reviews ready={props.ready} loggedIn={value.logged_in} setMsg={setMsg} showReviewBox={showReviewBox} setShow={setShow} anime_id={anime_id} user_id={value.userID} username={value.username}/> : <></>}
      </div>
    </div>
  </AnimeDetailsCTX.Provider>
  </>)
}

export default Animedetail;