import React, { Component, useEffect, useState, useContext } from 'react';
import { useLocation } from 'react-router-dom';
import { getCookie, has_review, get_reviews } from '../extra';
import axios from 'axios';
import { AnimeDetailsCTX } from '../AccountsComp/Anime_detail';

axios.defaults.xsrfHeaderName = "X-CSRFTOKEN";
axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.withCredentials = true;

const client = axios.create({
  baseURL: "https://infernovertigo.pythonanywhere.com"
});
const baseURL = "https://infernovertigo.pythonanywhere.com";

const Reviews = (props) =>{
  const value = useContext(AnimeDetailsCTX);

  useEffect(()=>{
    async function check_if_has(){
      //console.log(props)
      if(props.user_id == undefined || props.user_id == null){return;}
      const res = await has_review(props.user_id, props.anime_id).then((val)=>{
        return val.json();
      });//console.log(res);
      if(res["status"]){
        value.setRating(res["assoc"][0]["rating"]);
        value.setRecommend(res["assoc"][0]["recommend"])
        props.setMsg(res["assoc"][0]["msg"]);
        document.getElementById("write_review_btn").innerText="Edit Review"
      }
    }
    if(props.loggedIn){check_if_has();}

    get_reviews(value.anime_id, value.episodes, value.userEpisodes);
  }, [value.anime_id]);
  //review modal section
  function show_review_modal(e){
    if(props.showReviewBox){
      props.setShow(false);
    }else{
      props.setShow(true);
    }
  }

  return(
  <>
    <div id="review_options">
      <button onClick={(e)=>show_review_modal(e)} id="write_review_btn">Write a Review +</button>
      {false ? <div id="distribution"><span id="recommend"></span><span span id="neutral"></span><span span id="nope"></span></div>:<>
      <p style={{color:"white", fontSize:"20px", textAlign:"center"}}> Something cool here coming soon</p></>}
    </div>
    {false ? <div id="distributions">
      <p id="recommend_hold">Recommend: <span>10/10</span></p>
      <p id="none_hold">Nothing to say: <span>10/10</span></p>
      <p id="bad_hold">Not Good: <span>10/10</span></p>
    </div> : <></> }
    <hr></hr>
    <h1 id="no_reviews">No Reviews Yet</h1>
    <div id="review_area">
    
    </div>
  </>)
}

export default Reviews;