import React, { useState, useEffect, useContext } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import $ from 'jquery';
//import {boards} from './util2';
import { sort, first_ten, boards, sendView, reversed } from './util2';
import { getCookie } from '../extra';

const baseURL = "https://infernovertigo.pythonanywhere.com";

const Users = (props) => {
  var timeout = null;
  const [users, setUsers] = useState([]);
  const [showLoad, setIsLoading] = useState(true);
  const [original_board, setOriginal] = useState([]);
  const [user_id, setID] = useState(-1);
  const [clickTimeout, setTimeouts] = useState(null);
  const navigate = useNavigate();
  
  //get all available users
  useEffect(()=>{
    fetch(baseURL+"/usersV2", {
      method:"GET",
      headers:{
        "content-type":"application/json"
      }
    }).then((val)=>{return val.json()}).then((data)=>{
      setUsers(()=>[...data["persons"]]); 
      setIsLoading(false)
      fetch(baseURL+"/leaderboardV2", {
        method:"POST",
        body:JSON.stringify({
          "session":getCookie("sessionid"),
          "csrf":getCookie("csrftoken")
        }),
        headers:{
          "content-type":"application/json"
        }
      }).then((data2)=>data2.json()).then((val)=>{
        const board = [val["leaderboards"]["by_completed_shows"], val["leaderboards"]["by_watched_episodes"]]
        setOriginal(()=>{return board});
        setID(val["user_id"]);
        boards(board, val["user_id"]);
      })
    })
  }, []);

  //use effect for setting effect when clicking off user search
  useEffect(()=>{
    document.addEventListener("click", function(e){
      if(e.target.getAttribute("class") == "username_res" || e.target.getAttribute("id") == "user_search_id"){
        if(e.target.getAttribute("class") != null){      
          setTimeout(()=>{
            if(document.getElementById("user_searching_msg") != null){
              document.getElementById("user_searching_msg").style.display="none";
              const results = document.getElementById("user_result");
              for(let b = results.childNodes.length-1; b > -1; b--){
                results.removeChild(results.childNodes[b]);
              }
            }
          },300);
        }
      }else{
        if(document.getElementById("user_searching_msg") != null){
          document.getElementById("user_searching_msg").style.display="none";
          const results = document.getElementById("user_result");
          for(let b = results.childNodes.length-1; b > -1; b--){
            results.removeChild(results.childNodes[b]);
          }
        }
      }
    })
  }, []);

  function view_user(is_button){
    if(is_button){
      let user_input = document.getElementById("search_input");
      navigate(`/user/${user_input.value}`);
    }
  }

  function filterize(e){
    const option = document.getElementById("leaderboard_filter");
    const val = option.value;
    if(val == "By Completed"){
      boards(original_board, user_id, 0);
    }else if(val == "By Most Watched"){
      boards(original_board, user_id, 1);
    }else if(val == ""){
      boards(original_board, user_id, 0);
    }
  }

  async function search_user(e){
    let valueList = []
    let count = 0;
    let value = e.target.value;

    clearTimeout(timeout); // clear current timer and restart
    document.getElementById("user_searching_msg").style.display="flex";
    const results = document.getElementById("user_result");

    for(let b = results.childNodes.length-1; b > -1; b--){
      results.removeChild(results.childNodes[b]);
    }
    if(value == ""){
      document.getElementById("user_searching_msg").style.display="none";
      return;
    }

    timeout = setTimeout(async()=>{
      const resp = await fetch(baseURL + "/search_username", {
        "method":"POST",
        "body":JSON.stringify({"user":value}),
        "headers":{
          "Content-Type":"application/json"
        }
      }).then((value)=>{
        return value.json();
      }).then((data)=>{
        reversed(data["users"]);

        const final = sort(data["users"]);
        document.getElementById("user_searching_msg").style.display = "none";
        
        //where we show the users closest matches
        for(let k = 0; k< final.length; k++){
          const user_el = document.createElement("p");
          user_el.setAttribute("class", "username_res")
          const textNode = document.createTextNode(final[k][1])
          user_el.appendChild(textNode);
          user_el.addEventListener("click", sendView, textNode.textContent);
          results.appendChild(user_el);
        };
      })
    }, 2000);
    
    return;
    /*for(let b = results.childNodes.length-1; b > -1; b--){
      results.removeChild(results.childNodes[b]);
    }
    if(value == ""){
      document.getElementById("user_searching_msg").style.display="none";
      return;
    }
    timeout = setTimeout(()=>{
      let matches = "";
      for(let i=0; i< users.length; i++){
        const username = users[i][0].replace(/[-\:\,\"\[\]\;\'\+\=\!\`\~\(\)\*\&\^\%\$\>\<\?\/\\ ]+/g, "").toLowerCase().trim();
        //const title = "ReZEROStartingLifeinAnotherWorld".toLowerCase();
        if(count == 10){
          break;
        }
        let stepThrough = 0;
        let matches = 0;
        let inArow = 0;
        let previousJapName = null;
        let previousEngName = null;
        if(value.substring(0, value.length) == username.substring(0, value.length)){
          let matches = value.length/username.length;
          
          if(username.length == 0){
            matches=-1;
          }
          //console.log(matches)
          valueList.push([1.0+matches, users[i][0]])
          continue;
        }
        let trigger = false;

        outter1:for(let k=0; k < value.length; k++){
          inner1:for(let h=stepThrough; h < username.length; h++){
            if(stepThrough == username.length-1){
              let matched = matches/username.length;
              
              valueList.push([matched,  users[i][0]])
              
              break outter1;
            }
            if(inArow>1){
              matches+=1;
              //console.log(title);
            }
            if(value.charAt(k) == username.charAt(stepThrough)){
              if(trigger == true){
                stepThrough+=1
                continue inner1;
              }

              stepThrough = h;
              inArow+=1;
              stepThrough+=1;
              matches +=1;

              if(k == value.length-1){
                trigger=true;
                continue inner1;
              }
              break inner1;
            }
            inArow = 0;
            stepThrough+=1;
          }
        }
      }
      console.log(valueList);
      const final = first_ten(sort(valueList), 5);
      document.getElementById("user_searching_msg").style.display = "none";
      
      //where we show the users closest matches
      for(let k = 0; k< final.length; k++){
        const user_el = document.createElement("p");
        user_el.setAttribute("class", "username_res")
        const textNode = document.createTextNode(final[k][1])
        user_el.appendChild(textNode);
        user_el.addEventListener("click", sendView, textNode.textContent);
        results.appendChild(user_el);
      };
      /*const res = fetch(baseURL+"/get_queue", {
        method:"POST",
        body:JSON.stringify({
          "require_creds":false
        }),
        headers:{
          "content-type":'application/json'
        }
      })//
    }, 2000)*/
    //console.log("typing")
  }

  return (<>
    {!showLoad ? 
    <>
      <h2 style={{margin:"24.9px 0px 0px 10%",width:"80%", textAlign:"center"}}>Search Users:</h2>
      <form id="user_search" onSubmit={(e)=>{e.preventDefault()}} onKeyUp={search_user}><input id="user_search_id" type="search" placeholder='Search for a user...' list="user_search"/>
        <div id="user_searching_msg"><div className='msg'>Searching For user...</div><div className="loading_dots_cont"><p className="loading_dots">...</p></div></div>
        <div id="user_result">
          
        </div>
      </form>

      <div id="users_cont">
          {<>
          <h1 id="table_title">Leaderboards {"(Beta v2)"}</h1>
          <h4 id="usr_rank_cont">Your Rank: <span id="usr_rank">Loading Rank</span></h4>
          
          <div id="filter_container">
            <span className="filter_pieces" style={{color:"white"}}>Filter: </span>
            <span className="filter_pieces">
              <select id="leaderboard_filter">
                <option></option>
                <option selected={true}>By Completed</option>
                <option>By Most Watched</option>
              </select>
            </span>
            <span>
              <button id="filt_apply_btn" className="filter_apply" onClick={(e)=>{filterize(e)}}>Apply</button>
            </span>
            
          </div>
          
          <div id="table_cont">
            <table id="leaderboard_table">
              <tr id="table_leaderboard_head1">
                <th>Rank</th>
                <th>Username</th>
                <th>Episodes Watched</th>
                <th>Completed Shows</th>
              </tr>
              <td colSpan={4} id="redirect_cont">
                <div class="loader"></div>
                <span id="loading_id">LOADING LEADERBOARD</span>
              </td>
            </table>
          </div>
        </>
        }
      </div>
      </>
      :
      <div style={{"textAlign":"center", "marginTop":"50px"}}>
        <div class="loader"></div>
        <span id="loading_id">Loading</span>
      </div>}
    </>
  )
}

export default Users;