import React, { Component, useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { getCookie, send_review } from '../../extra';
import Modal from "react-modal";
import axios from 'axios';

axios.defaults.xsrfHeaderName = "X-CSRFTOKEN";
axios.defaults.xsrfCookieName = "csrftoken";
axios.defaults.withCredentials = true;

function ViewerIn(props){
  useEffect(()=>{
    document.getElementById("review_box").value=props.value.msg;
    document.getElementById("review_rating").value = props.value.review_rating;
    document.getElementById("rec_check").value = props.value.review_recommend;
    
    word_count();
  })
  function word_count(){
    const count = document.getElementById("count");
    const textArea = document.getElementById("review_box");
  
    const length = textArea.value.trim().length;
    count.innerText = length.toString();
  
    if(length == 1000){count.style.color="red"}
    else{count.style.color="orange"}
  }

  return(<>
    <form>
      <textarea onChange={(e)=>word_count()} placeholder='Write a review' id="review_box" maxLength={1000}></textarea>
      <br></br>
      <div id="action_cont_review_box">
        <div id="wordCount_review_cont">
          <p>Character Limit: <span id="count">0</span>/<span>1000</span></p>
        </div>
        <div id="recommend_review_cont">
        <label id="rec_label">Would you reccomend?: </label>
          <select id="rec_check">
            <option></option>
            <option>Yep</option>
            <option selected>Neutral</option>
            <option>Nope</option>
          </select>
        </div>
        <div id="rating_review_cont">
          <label>Rating: </label>
          <select id="review_rating">
            <option>0</option>
            <option>1</option>
            <option>2</option>
            <option>3</option>
            <option>4</option>
            <option>5</option>
            <option>6</option>
            <option>7</option>
            <option>8</option>
            <option>9</option>
            <option>10</option>
          </select>
        </div>
        <button onClick={(e)=>send_review(e, props.value.anime_id, props.value.user_id, props.value.userEpisodes, props.closeModal, props.value.setMsg, props.value)} id="submit_review_btn" type="button">Submit</button>
      </div>
      <div><p id="review_error_handler"></p></div>
      <p style={{color:"red", margin:"0px", fontWeight:"800"}}>Note: You have to have added the anime once to your list or watched 1 episode to review.</p>
    </form>
  </>
    
  )
}

export default ViewerIn;